ALTER TABLE "reprocann_documents" ADD CONSTRAINT "reprocann_documents_withdrawal_check" CHECK (("reprocann_documents"."withdrawn_at" is null and "reprocann_documents"."withdrawn_by" is null and "reprocann_documents"."withdrawal_reason" is null and "reprocann_documents"."kept_document_id" is null) or ("reprocann_documents"."withdrawn_at" is not null and "reprocann_documents"."withdrawn_by" is not null and "reprocann_documents"."withdrawal_reason" is not null and (("reprocann_documents"."withdrawal_reason" = 'duplicado' and "reprocann_documents"."kept_document_id" is not null and "reprocann_documents"."kept_document_id" <> "reprocann_documents"."id") or ("reprocann_documents"."withdrawal_reason" <> 'duplicado' and "reprocann_documents"."kept_document_id" is null))));